-- drizzle/migrations/0006_seed_juridicas_e_humanas.sql
-- Questões de matérias jurídicas, criminologia, direitos humanos e conhecimentos regionais

INSERT INTO public.questions (materia, topico, enunciado, alternativas, correta, explicacao) VALUES
-- DIREITO CONSTITUCIONAL
('Direito Constitucional','Inviolabilidade do domicílio','Durante patrulhamento noturno, policiais ouvem pedidos de socorro e presenciam, pela janela de uma residência, uma agressão em curso. Sem consentimento do morador, a entrada no imóvel é constitucionalmente permitida para','["cumprir qualquer mandado judicial, independentemente do horário.","realizar busca preventiva baseada exclusivamente na localização do imóvel.","interromper o flagrante delito e prestar socorro à vítima.","efetuar fiscalização domiciliar de rotina, dispensada qualquer justificativa.","averiguar denúncia anônima, ainda que ausentes outros elementos."]'::jsonb,2,'O art. 5º, XI, da Constituição permite ingresso domiciliar, mesmo à noite e sem consentimento, em flagrante delito, desastre ou para prestar socorro.'),
('Direito Constitucional','Direitos da pessoa presa','Após uma prisão em flagrante, o responsável pela condução informa ao preso que ele deverá responder a todas as perguntas, sem assistência jurídica. À luz da Constituição, a orientação correta é que o preso','["pode permanecer calado e tem assegurada a assistência da família e de advogado.","deve responder sobre os fatos antes de exercer o direito ao silêncio.","somente terá assistência de advogado depois do oferecimento da denúncia.","pode ficar calado apenas se apresentar previamente uma justificativa.","perde o direito à assistência familiar quando a prisão ocorre em flagrante."]'::jsonb,0,'O art. 5º, LXIII, da Constituição assegura ao preso informação sobre seus direitos, inclusive permanecer calado, e assistência da família e de advogado.'),
('Direito Constitucional','Liberdade de associação','Uma associação civil de apoio a policiais, regularmente constituída e com fins lícitos, é alvo de medida que pretende dissolvê-la compulsoriamente. Segundo a Constituição, essa dissolução depende de','["ato fundamentado do secretário de segurança pública.","portaria da autoridade policial responsável pela investigação.","deliberação administrativa do Ministério Público.","decisão judicial, ainda que sujeita a recurso sem trânsito em julgado.","decisão judicial transitada em julgado."]'::jsonb,4,'O art. 5º, XIX, da Constituição exige decisão judicial para suspensão de atividades e decisão judicial transitada em julgado para dissolução compulsória de associações.'),
('Direito Constitucional','Órgãos de segurança pública','Em uma aula de formação, discute-se a atribuição constitucional da polícia civil estadual na apuração de infrações penais. Ressalvada a competência da União, cabe à polícia civil exercer','["o policiamento ostensivo e a preservação da ordem pública.","as funções de polícia judiciária e a apuração de infrações penais, exceto as militares.","a polícia judiciária da União com exclusividade.","o patrulhamento ostensivo das rodovias federais.","a apuração exclusiva das infrações penais militares estaduais."]'::jsonb,1,'O art. 144, § 4º, da Constituição atribui às polícias civis a polícia judiciária e a apuração de infrações penais, exceto militares, ressalvada a competência da União.'),
('Direito Constitucional','Habeas corpus','Um cidadão é mantido em uma delegacia por ordem manifestamente ilegal, sem possibilidade de sair. Sua irmã, que não é advogada, pretende buscar proteção judicial imediata à liberdade de locomoção. Cabe','["mandado de segurança, pois o habeas corpus exige advogado.","habeas data, para obter diretamente a soltura.","ação popular, destinada à proteção de qualquer direito individual.","habeas corpus, que pode ser impetrado pela própria irmã.","mandado de injunção, independentemente de omissão normativa."]'::jsonb,3,'O art. 5º, LXVIII, da Constituição prevê habeas corpus contra coação ilegal à locomoção. O art. 654 do CPP permite impetração por qualquer pessoa.'),

-- DIREITO ADMINISTRATIVO
('Direito Administrativo','Princípios da Administração Pública','Uma delegacia divulga campanha institucional de prevenção a golpes com fotografias e slogans que promovem pessoalmente seu dirigente. Segundo a Constituição, essa publicidade contraria especialmente o princípio da','["autotutela.","impessoalidade.","continuidade.","especialidade.","segurança jurídica."]'::jsonb,1,'O art. 37, § 1º, da Constituição veda nomes, símbolos ou imagens que caracterizem promoção pessoal na publicidade oficial, concretizando a impessoalidade.'),
('Direito Administrativo','Revogação de atos administrativos','A direção de um órgão policial federal considera inconveniente manter determinado ato discricionário válido, que não gerou direitos adquiridos. Para retirá-lo por razões de mérito administrativo, deverá promover sua','["anulação, com fundamento obrigatório em ilegalidade.","convalidação, para eliminar sua eficácia futura.","cassação, independentemente de descumprimento pelo destinatário.","revogação, respeitados os limites legais.","anulação judicial, por razões de oportunidade."]'::jsonb,3,'O art. 53 da Lei nº 9.784/1999 permite revogar atos por conveniência ou oportunidade, respeitados os direitos adquiridos; a anulação decorre de ilegalidade.'),
('Direito Administrativo','Responsabilidade civil do Estado','Durante serviço, um policial, agindo nessa qualidade, causa culposamente dano a terceiro. Demonstrados o dano e o nexo causal, sem excludentes, a responsabilidade estatal e o regresso contra o agente são, respectivamente,','["objetiva e condicionado à demonstração de dolo ou culpa do agente.","subjetiva e independente de dolo ou culpa do agente.","objetiva e automaticamente devido, mesmo sem dolo ou culpa.","subjetiva e condicionado exclusivamente à condenação criminal.","inexistente e obrigatório contra o agente."]'::jsonb,0,'O art. 37, § 6º, da Constituição estabelece responsabilidade objetiva do Estado e assegura regresso contra o agente nos casos de dolo ou culpa.'),
('Direito Administrativo','Deveres do servidor público','Um servidor policial submetido a estatuto funcional recebe ordem de superior para inserir informação sabidamente falsa em documento oficial. Quanto ao dever de obediência, o servidor deve','["cumprir a ordem, pois a hierarquia afasta sua responsabilidade.","cumprir a ordem se ela for posteriormente confirmada por escrito.","executar a determinação e contestá-la apenas após sua consumação.","obedecer sempre que o superior assumir verbalmente a responsabilidade.","recusar o cumprimento, por se tratar de ordem manifestamente ilegal."]'::jsonb,4,'O regime estatutário impõe cumprir ordens superiores, exceto quando manifestamente ilegais.'),
('Direito Administrativo','Motivação dos atos administrativos','Em processo administrativo, a autoridade indefere pedido de servidor policial que busca o reconhecimento de um direito funcional. A decisão deve ser','["imotivada, porque pedidos funcionais são matéria interna.","motivada apenas se houver determinação judicial expressa.","motivada, com indicação dos fatos e dos fundamentos jurídicos.","fundamentada somente quando reconhecer o direito solicitado.","substituída obrigatoriamente por parecer sem conteúdo decisório."]'::jsonb,2,'A legislação de processo administrativo exige motivação, com indicação expressa dos fatos e dos fundamentos jurídicos, nos atos que neguem, limitem ou afetem direitos.'),

-- DIREITO PENAL
('Direito Penal','Lugar do crime','Um investigado envia do exterior um artefato para executar um homicídio. A explosão e a morte ocorrem no Brasil. Para definir o lugar do crime, o Código Penal considera a infração praticada','["apenas onde o investigado preparou o artefato.","exclusivamente no local em que ocorreu a morte.","somente no país de residência do investigado.","apenas no território em que começou a execução.","onde ocorreu a ação ou omissão, no todo ou em parte, e onde o resultado ocorreu ou deveria ocorrer."]'::jsonb,4,'O art. 6º do Código Penal adota a teoria da ubiquidade: considera tanto o local da ação ou omissão quanto aquele onde o resultado ocorreu ou deveria ocorrer.'),
('Direito Penal','Tentativa','Durante um roubo, o agente inicia a execução mediante grave ameaça, mas é contido por policiais antes de subtrair qualquer bem. Reconhecida a tentativa, sua pena, salvo disposição em contrário, corresponde à do crime consumado','["sem qualquer redução, porque houve grave ameaça.","diminuída de um a dois terços.","diminuída obrigatoriamente pela metade.","substituída automaticamente por multa.","aumentada de um a dois terços."]'::jsonb,1,'O art. 14, II e parágrafo único, do Código Penal prevê tentativa e redução de um a dois terços sobre a pena do crime consumado.'),
('Direito Penal','Desistência voluntária','Um agente inicia a execução de um furto, mas, embora pudesse prosseguir sem impedimentos externos, decide voluntariamente interrompê-la antes da subtração. Pela regra da desistência voluntária, ele responde','["sempre por furto consumado.","necessariamente por tentativa de furto.","por tentativa, com redução obrigatória de metade da pena.","somente pelos atos já praticados que constituam infração penal.","por furto consumado, com exclusão apenas da pena de multa."]'::jsonb,3,'Conforme o art. 15 do Código Penal, quem voluntariamente desiste de prosseguir na execução responde apenas pelos atos já praticados, se penalmente típicos.'),
('Direito Penal','Legítima defesa','Um policial presencia agressão injusta e atual contra um pedestre e intervém usando moderadamente os meios necessários para fazê-la cessar. Presentes esses elementos, a atuação caracteriza','["legítima defesa de terceiro.","estado de necessidade, obrigatoriamente.","exercício arbitrário das próprias razões.","legítima defesa apenas se o policial também for atacado.","estrito cumprimento do dever legal em qualquer intensidade de reação."]'::jsonb,0,'O art. 25 do Código Penal admite legítima defesa de direito próprio ou alheio contra agressão injusta, atual ou iminente, com uso moderado dos meios necessários.'),
('Direito Penal','Peculato','Um policial responsável pela guarda de um notebook apreendido, do qual tem posse em razão do cargo, incorpora dolosamente o bem ao próprio patrimônio. A conduta configura','["furto simples.","apropriação indébita comum.","peculato-apropriação.","concussão.","corrupção passiva."]'::jsonb,2,'O art. 312, caput, do Código Penal tipifica a apropriação, pelo funcionário público, de bem móvel público ou particular de que tenha posse em razão do cargo.'),

-- DIREITO PROCESSUAL PENAL
('Direito Processual Penal','Prisão em flagrante','Um comerciante presencia um furto em execução e detém o autor imediatamente, entregando-o à equipe policial. Segundo o Código de Processo Penal, a captura pelo particular é','["permitida, pois qualquer pessoa pode prender quem esteja em flagrante delito.","proibida, pois somente policiais podem efetuar prisão em flagrante.","válida apenas se houver mandado judicial previamente expedido.","obrigatória, sob pena de responsabilidade penal por omissão.","permitida somente quando o crime envolver violência contra pessoa."]'::jsonb,0,'O art. 301 do CPP permite a qualquer pessoa prender quem esteja em flagrante delito (flagrante facultativo) e impõe esse dever às autoridades policiais e seus agentes (flagrante obrigatório).'),
('Direito Processual Penal','Exame de corpo de delito','Na apuração de uma agressão que deixou vestígios, o investigado confessa integralmente o fato. Quanto à materialidade, o CPP determina que','["a confissão dispensa qualquer exame pericial.","o boletim de ocorrência sempre substitui a perícia.","o exame somente será feito se solicitado pela defesa.","o exame de corpo de delito, direto ou indireto, é indispensável, não o suprindo a confissão.","a autoridade policial escolha livremente entre confissão e exame."]'::jsonb,3,'O art. 158 do CPP exige exame de corpo de delito, direto ou indireto, quando a infração deixar vestígios, e estabelece que a confissão não pode supri-lo.'),
('Direito Processual Penal','Indisponibilidade do inquérito','Após concluir diligências, um delegado entende que os elementos colhidos não demonstram infração penal. Diante dessa conclusão, conforme o CPP, a autoridade policial','["pode arquivar o inquérito por decisão administrativa fundamentada.","não pode mandar arquivar os autos do inquérito.","deve destruir os autos após comunicar o investigado.","pode arquivar o inquérito se houver concordância da vítima.","deve converter o inquérito em processo judicial absolutório."]'::jsonb,1,'O art. 17 do CPP estabelece expressamente que a autoridade policial não poderá mandar arquivar autos de inquérito.'),
('Direito Processual Penal','Prisão preventiva','Durante a investigação, surgem requisitos para prisão preventiva. Sem requerimento do Ministério Público nem representação da autoridade policial, segundo o CPP, o magistrado','["deve decretá-la de ofício sempre que o crime for grave.","pode decretá-la de ofício se justificar a urgência.","pode decretá-la de ofício após ouvir informalmente a vítima.","deve determinar ao delegado que a decrete administrativamente.","não pode decretá-la de ofício."]'::jsonb,4,'O art. 311 do CPP condiciona a prisão preventiva a requerimento do MP ou representação da autoridade policial, vedada a decretação de ofício pelo juiz.'),
('Direito Processual Penal','Prova e fundamentação','Em ação penal, a acusação apresenta apenas elementos informativos do inquérito, sem confirmação em contraditório judicial e sem provas cautelares ou irrepetíveis. Pelo CPP, a condenação baseada nesses elementos é','["válida sempre que o delegado tiver indiciado o réu.","obrigatória quando o acusado permanecer em silêncio.","vedada, pois elementos da investigação não bastam isoladamente para fundamentar a decisão.","válida se o inquérito tiver sido concluído no prazo legal.","permitida quando a defesa não requerer novas diligências."]'::jsonb,2,'O art. 155 do CPP veda a condenação fundada exclusivamente nos elementos informativos colhidos na investigação, ressalvadas provas cautelares, não repetíveis e antecipadas.'),

-- LEGISLAÇÃO PENAL ESPECIAL
('Legislação Penal Especial','Lei de Drogas: tráfico','Policiais flagram um indivíduo que, sem autorização legal, mantém cocaína em depósito para venda a terceiros, sem que ainda tenha havido entrega ou recebimento de dinheiro. Pela Lei nº 11.343/2006, essa conduta','["somente será tráfico após a primeira venda comprovada.","configura apenas ato preparatório penalmente irrelevante.","depende de lucro efetivo para caracterizar crime.","consuma o crime de tráfico de drogas, pois ter em depósito é um dos núcleos do tipo.","caracteriza necessariamente posse para consumo pessoal."]'::jsonb,3,'O art. 33, caput, da Lei nº 11.343/2006 prevê a conduta de ter em depósito sem autorização como crime consumado de tráfico de drogas, independente de venda efetiva.'),
('Legislação Penal Especial','Abuso de autoridade','Ao apurar conduta de agente público com base na Lei nº 13.869/2019, o tipo penal exige elemento subjetivo específico consistente na finalidade de','["prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou por mero capricho ou satisfação pessoal.","cometer qualquer irregularidade, mesmo exclusivamente culposa.","descumprir norma administrativa, sem necessidade de dolo específico.","obter necessariamente vantagem econômica direta para o agente.","produzir lesão corporal de qualquer gravidade na vítima."]'::jsonb,0,'O art. 1º, § 1º, da Lei nº 13.869/2019 exige como especial fim de agir o propósito de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou por mero capricho ou satisfação pessoal.'),
('Legislação Penal Especial','Crime de tortura','Para obter uma confissão, um agente constrange pessoa sob sua custódia mediante violência, causando-lhe sofrimento físico. Conforme a Lei nº 9.455/1997, essa conduta tipifica','["apenas falta disciplinar se não houver lesão grave permanente.","constrangimento permitido para elucidação de crimes graves.","crime de tortura, ainda que a confissão não venha a ser obtida.","crime de tortura apenas se resultar em lesão gravíssima ou morte.","exercício regular do direito de investigar."]'::jsonb,2,'O art. 1º, I, a, da Lei nº 9.455/1997 pune o constrangimento com emprego de violência para obtenção de informação ou confissão, consumando-se com o sofrimento imposto.'),
('Legislação Penal Especial','Lei Maria da Penha','Uma mulher relata agressões praticadas por ex-namorado com quem manteve relação íntima de afeto, sem nunca terem residido sob o mesmo teto. A aplicação da Lei nº 11.340/2006','["depende obrigatoriamente de coabitação pretérita.","exige a existência de filhos comuns do relacionamento.","aplica-se ao caso, pois a lei independe de coabitação.","fica afastada em virtude do término do relacionamento anterior.","exige casamento civil ou união estável formalizada."]'::jsonb,2,'O art. 5º, III, da Lei nº 11.340/2006 inclui violência em qualquer relação íntima de afeto, na qual o agressor conviva ou tenha convivido com a ofendida, independentemente de coabitação.'),
('Legislação Penal Especial','Estatuto do Desarmamento','Em busca domiciliar lícita, policiais encontram uma arma de fogo de uso permitido e com numeração íntegra guardada na residência do agente sem o devido registro. Sem outras circunstâncias, a conduta caracteriza','["porte ilegal de arma de fogo de uso restrito.","posse irregular de arma de fogo de uso permitido.","comércio ilegal de arma de fogo.","tráfico ilícito de arma de fogo.","conduta atípica, por se encontrar no interior da residência."]'::jsonb,1,'O art. 12 da Lei nº 10.826/2003 tipifica possuir ou manter sob sua guarda arma de fogo de uso permitido no interior de sua residência em desacordo com determinação legal.'),

-- DIREITOS HUMANOS
('Direitos Humanos','Proibição da tortura','Durante uma investigação urgente, sugere-se infligir maus-tratos ao suspeito para salvar uma vítima. Segundo a Convenção Americana sobre Direitos Humanos, essa conduta é','["proibida de forma absoluta, mesmo diante da gravidade do delito investigado.","permitida em caso de iminente risco à vida de terceiros.","admitida mediante autorização judicial fundamentada.","legítima quando não deixar sequelas físicas permanentes.","tolerada caso o suspeito registre antecedentes graves."]'::jsonb,0,'A proibição da tortura na Convenção Americana sobre Direitos Humanos (art. 5º, 2) possui caráter absoluto e inderrogável, mesmo em situações excepcionais ou de perigo público.'),
('Direitos Humanos','Presunção de inocência','Uma autoridade policial declara à imprensa que o simples oferecimento de denúncia prova a culpabilidade do investigado. Conforme o Pacto de San José da Costa Rica, essa declaração','["expressa a consequência jurídica ordinária da peça acusatória.","viola o direito à presunção de inocência enquanto não se comprovar legalmente a culpa.","é plenamente válida diante de elementos indiciários convergentes.","substitui a necessidade de instrução probatória em juízo.","é legítima quando o réu se encontra sob custódia cautelar."]'::jsonb,1,'O art. 8º, 2, da Convenção Americana consagra que toda pessoa acusada de delito tem direito a que se presuma sua inocência enquanto não se comprove legalmente sua culpa.'),
('Direitos Humanos','Garantias da pessoa presa','Uma pessoa presa exige permanecer em silêncio e contatar um defensor. À luz dos direitos fundamentais da Constituição Federal, o responsável pela custódia deve','["condicionar o silêncio à autorização do juiz da causa.","exigir respostas sobre a autoria antes de franquear o defensor.","assegurar a informação sobre seus direitos, incluindo silêncio e assistência jurídica e familiar.","advertir que o silêncio faz presumir a veracidade da imputação.","permitir contato com defensor somente após concluída a oitiva inicial."]'::jsonb,2,'O art. 5º, LXIII, da CF assegura ao preso o direito de permanecer calado e a assistência de advogado e da família.'),
('Direitos Humanos','Tratados de direitos humanos','Um tratado internacional de direitos humanos foi aprovado pelo Congresso em dois turnos, por três quintos dos votos em cada Casa. Nos termos da Constituição Federal, ele adquire status de','["lei ordinária federal.","decreto autônomo regulamentar.","lei complementar nacional.","emenda constitucional.","resolução legislativa colegiada."]'::jsonb,3,'O art. 5º, § 3º, da CF prevê que os tratados e convenções internacionais sobre direitos humanos aprovados pelo rito das emendas constitucionais são a elas equivalentes.'),
('Direitos Humanos','Separação de presos','Em um estabelecimento penal, propõe-se a permanência conjunta de réus provisórios e sentenciados definitivos. A Convenção Americana sobre Direitos Humanos prevê que os processados','["devem ser mantidos juntos com os condenados para viabilizar a disciplina prisional.","podem sofrer cumprimento antecipado da pena aplicada aos já condenados.","serão separados dos condenados e submetidos a tratamento próprio à condição de não condenados.","somente se separam dos condenados se recolherem taxa de custódia carcerária.","não recebem nenhuma diferenciação legal perante a execução das sanções."]'::jsonb,2,'O art. 5º, item 4, da CADH estabelece que os réus processados devem ficar separados dos condenados e receber tratamento adequado à condição de pessoas não condenadas.'),

-- CRIMINOLOGIA
('Criminologia','Teoria das atividades rotineiras','Ao estudar índices de criminalidade urbana, constata-se a frequência de delitos onde convergem três fatores elementares. Na teoria das atividades rotineiras (Cohen e Felson), o crime depende da convergência de','["transtorno psíquico, miséria e reincidência criminológica.","agente motivado, alvo vulnerável adequado e ausência de vigilante capaz.","rigor da pena privativa de liberdade, confissão do réu e reincidência.","estigmatização penal, desemprego e herança genética familiar.","condenação anterior, idade jovem e ambiente de marginalização."]'::jsonb,1,'A Teoria das Atividades Rotineiras analisa o crime a partir da convergência no tempo e no espaço de um agressor motivado, um alvo adequado e a ausência de um guardião capaz.'),
('Criminologia','Teoria da anomia em Merton','Ao analisar a adaptação de indivíduos perante os objetivos culturais e os meios institucionalizados, Merton designa por inovação a postura em que o indivíduo','["aceita as metas culturais de sucesso, mas recorre a meios ilícitos para atingi-las.","rejeita as metas culturais e os meios legítimos, isolando-se do convívio social.","rejeita os fins culturais de riqueza, mas cumpre rigidamente as normas e rotinas.","aceita integralmente tanto os fins sociais quanto os meios institucionais previstos.","propõe a substituição violenta de toda a ordem institucional existente."]'::jsonb,0,'Na tipologia anômica de Robert Merton, a inovação ocorre quando o indivíduo assimila os fins culturais de sucesso financeiro, mas rejeita ou não tem acesso aos meios lícitos, apelando a condutas delituosas.'),
('Criminologia','Cifra negra','Uma pesquisa de vitimização demonstra expressiva quantidade de crimes patrimoniais não comunicados às autoridades. A expressão criminológica cifra negra corresponde','["aos delitos de homicídio sem autoria identificada pelo inquérito policial.","à taxa de reincidência apurada pelo sistema penitenciário estadual.","à diferença entre a criminalidade real ocorrida e a criminalidade formalmente registrada.","ao número de prisões em flagrante convertidas em preventivas.","à proporção de inquéritos policiais arquivados por falta de provas."]'::jsonb,2,'A cifra negra representa a parcela da criminalidade real que não chega ao conhecimento dos órgãos estatais e, por isso, não consta das estatísticas oficiais.'),
('Criminologia','Modelos de prevenção criminal','Um programa governamental que investe em saneamento básico, educação de tempo integral e geração de empregos atua na prevenção criminal classificada como','["terciária, porque visa à reabilitação do egresso do sistema prisional.","secundária, porque se volta de forma seletiva a grupos de alto risco delinquencial.","situacional, porque atua mediante obstáculos arquitetônicos imediatos.","primária, porque incide nas causas fundamentais da sociedade antes da eclosão do delito.","repressiva, com esteio nas forças de operações especiais policiais."]'::jsonb,3,'A prevenção primária atua sobre as raízes sociais e econômicas do delito, promovendo direitos sociais universais antes que a delinquência se manifeste.'),
('Criminologia','Teoria da desorganização social','Associando criminalidade a fatores ecológicos urbanos, a Escola de Chicago (Shaw e McKay) sustentou que elevadas taxas de delinquência decorrem principalmente da','["predisposição genética herdada por moradores de certas regiões periféricas.","fragilidade do controle social informal e deterioração comunitária decorrente da instabilidade residencial.","ausência total de leis punitivas capazes de intimidar potenciais infratores.","escolha puramente racional do agente que pondera custo e benefício da pena.","atuação desmedida das agências de controle que estigmatizam o condenado."]'::jsonb,1,'A Teoria da Desorganização Social vincula taxas de criminalidade à instabilidade social, carência de coesão comunitária e enfraquecimento dos laços sociais informais na vizinhança.'),

-- HISTÓRIA E GEOGRAFIA DO AMAPÁ
('História e Geografia do Amapá','Contestado franco-brasileiro','A disputa territorial sobre o Contestado do Amapá entre Brasil e França foi pacificada no ano de 1900 por arbitramento internacional liderado pelo','["governo da Confederação Suíça, favorável à tese brasileira defendida pelo Barão do Rio Branco.","presidente dos Estados Unidos da América, que acolheu a tese da Guiana Francesa.","tribunal de arbitragem de Haia, delimitando o Rio Oiapoque como território neutro.","rei de Portugal, por força dos limites estabelecidos no Tratado de Utrecht.","imperador da Alemanha, que determinou a divisão igualitária do território litigioso."]'::jsonb,0,'O Laudo Suíço de 1º de dezembro de 1900, elaborado pelo Conselho Federal Suíço e defendido com maestria pelo Barão do Rio Branco, garantiu ao Brasil a posse definitiva do território contestado.'),
('História e Geografia do Amapá','Ocupação colonial: Mazagão Velho','A vila de Mazagão Velho foi fundada na Amazônia colonial do século XVIII no contexto das diretrizes pombalinas de ocupação territorial. Seus pioneiros eram famílias transferidas de uma possessão portuguesa situada no atual','["território de Angola.","território de Moçambique.","território de Cabo Verde.","Marrocos, no norte da África.","território de São Tomé e Príncipe."]'::jsonb,3,'Mazagão Velho foi construída para abrigar colonos transferidos da praça-forte portuguesa de Mazagão, no atual Marrocos, abandonada pela Coroa portuguesa em 1769.'),
('História e Geografia do Amapá','Unidades de conservação','O Parque Nacional Montanhas do Tumucumaque, localizado na porção noroeste do Estado do Amapá e norte do Pará, destaca-se por ser','["uma área prioritária para o cultivo agropecuário intensivo na Amazônia.","uma das maiores unidades de conservação de proteção integral de floresta tropical contínua do planeta.","um distrito industrial minerário com exploração autorizada sem licença ambiental.","uma terra pública voltada prioritariamente ao assentamento urbano populacional.","uma área de livre trânsito aduaneiro com a Guiana Francesa e o Suriname."]'::jsonb,1,'Criado em 2002, o Parque Nacional Montanhas do Tumucumaque protege ecossistemas amazônicos intactos e é um dos maiores parques de floresta tropical do mundo.'),
('História e Geografia do Amapá','Hidrografia estadual','No extremo sul e sudoeste do Amapá, fazendo divisa natural com o estado do Pará e banhando municípios como Laranjal do Jari e Vitória do Jari, localiza-se o expressivo curso do Rio','["Jari.","Oiapoque.","Araguari.","Amapari.","Matapi."]'::jsonb,0,'O Rio Jari corre no sudoeste do Amapá, demarcando a fronteira interestadual com o Pará e banhando a região do Vale do Jari.'),
('História e Geografia do Amapá','Relevo amapaense','No relevo do Estado do Amapá, encontram-se baixadas litorâneas e áreas mais elevadas do Planalto das Guianas no interior. No noroeste do estado, na fronteira com o Escudo Guianês, destaca-se a','["Serra da Mantiqueira.","Serra do Tumucumaque.","Serra dos Carajás.","Serra da Canastra.","Serra do Espinhaço."]'::jsonb,1,'A Serra do Tumucumaque situa-se na fronteira norte e noroeste do estado, integrando o maciço do Planalto das Guianas.'),

-- LEGISLAÇÃO ESTADUAL (PC-AP)
('Legislação Estadual (PC-AP)','Competência institucional','Nos termos da Constituição do Estado do Amapá e do art. 144 da CF, compete privativamente à Polícia Civil do Estado do Amapá exercer as funções de','["policiamento ostensivo e preservação imediata da ordem pública.","polícia judiciária e apuração de infrações penais comuns, ressalvada a competência da União e as militares.","defesa externa das fronteiras estaduais e controle de alfândega.","julgamento colegiado de crimes praticados por servidores públicos estaduais.","defesa processual e consultoria jurídica do Poder Executivo estadual."]'::jsonb,1,'À Polícia Civil cabe a função de polícia judiciária e a apuração das infrações penais, exceto as militares e ressalvada a competência da União.'),
('Legislação Estadual (PC-AP)','Direção institucional','De acordo com o texto constitucional, a direção-geral da Polícia Civil do Estado do Amapá é órgão privativo exercido por ocupante do cargo de','["oficial da ativa da Polícia Militar.","promotor de justiça com atuação criminal.","delegado de polícia de carreira.","juiz auditor militar estadual.","qualquer servidor público titular de cargo técnico na corporação."]'::jsonb,2,'Conforme o § 4º do art. 144 da CF/88 e disposições estaduais correspondentes, as polícias civis são dirigidas por delegados de polícia de carreira.'),
('Legislação Estadual (PC-AP)','Finalidade do inquérito policial','Na estrutura investigativa da Polícia Civil do Estado do Amapá, o inquérito policial tem por precípua finalidade','["aplicar sanções penais de pequena complexidade na esfera administrativa.","reunir elementos de materialidade e autoria da infração penal para subsidiar a propositura da ação penal.","substituir o julgamento pelo tribunal do júri nas infrações dolosas contra a vida.","declarar a inocência compulsória do investigado com eficácia de coisa julgada.","promover a conciliação pecuniária obrigatória de todos os crimes capitulados."]'::jsonb,1,'O inquérito policial tem caráter preparatório e informativo, colhendo indícios de autoria e prova da materialidade que fundamentarão a denúncia do Ministério Público.'),
('Legislação Estadual (PC-AP)','Direitos da pessoa conduzida','Segundo a Constituição do Estado do Amapá, à pessoa que for presa ou conduzida em operação policial é expressamente assegurado o direito de','["ser mantida incomunicável por prazo improrrogável de até quarenta e oito horas.","identificar os responsáveis por sua prisão ou por seu interrogatório policial.","dispensar a realização de auto de prisão em flagrante caso não possua advogado.","ser encaminhada a estabelecimento prisional fora da comarca sem ordem escrita.","escolher livremente a autoridade judiciária competente para sua audiência."]'::jsonb,1,'A Constituição do Estado do Amapá, alinhada à Carta Magna, assegura ao preso o direito à identificação dos responsáveis por sua prisão ou interrogatório policial.'),
('Legislação Estadual (PC-AP)','Separação de Poderes','Na organização política do Estado do Amapá estabelecida por sua Constituição, são Poderes do Estado, independentes e harmônicos entre si, apenas:','["o Executivo, o Legislativo, o Judiciário e a Segurança Pública.","o Legislativo, o Executivo e o Judiciário.","o Executivo, o Ministério Público e o Tribunal de Contas.","o Legislativo, o Executivo e as Forças Policiais.","o Judiciário, o Ministério Público e a Defensoria Pública."]'::jsonb,1,'Nos termos do art. 1º, § 2º, da Constituição Estadual, são Poderes do Estado, independentes e harmônicos entre si, o Legislativo, o Executivo e o Judiciário.')
ON CONFLICT (materia, enunciado) DO NOTHING;
